mapper.select:
select l.log_id, l.customer_id, c.customer_name, l.change_type,
       l.changed_fields, l.before_summary, l.after_summary,
       l.operator_user_id, l.operator_name, l.source_client,
       l.create_time
from inv_customer_service_change_log l
inner join inv_customer c on c.customer_id = l.customer_id
where l.shop_dept_id = #{shopDeptId}
  and c.shop_dept_id = #{shopDeptId}
and l.customer_id = #{customerId}
and l.change_type = #{changeType}
and l.source_client = #{sourceClient}

    and l.operator_name like concat('%', #{operatorName}, '%')


    and l.create_time >= #{params.beginTime}


    and l.create_time <= #{params.endTime}

order by l.create_time desc, l.log_id desc

mapper.update:
update inv_customer_service_profile
set version = version + 1, update_by = #{updateBy}, update_time = sysdate()
where customer_id = #{customerId} and version = #{version}

mapper.sql:
customer_id = #{customerId} and shop_dept_id = #{shopDeptId}
and record_id <= #{snapshotMaxRecordId}
and service_date >= #{dateFrom}
and service_date < date_add(#{dateTo}, interval 1 day)

    and (tea_served like concat('%', #{keywordLike}, '%') escape '!'
      or preference_snapshot like concat('%', #{keywordLike}, '%') escape '!'
      or caution_snapshot like concat('%', #{keywordLike}, '%') escape '!'
      or service_note like concat('%', #{keywordLike}, '%') escape '!'
      or service_user_name like concat('%', #{keywordLike}, '%') escape '!')

mapper.select:
select record_id, customer_id, service_date, service_user_id, service_user_name, party_size, tea_served, preference_snapshot, caution_snapshot, service_note, consumption_amount, shop_dept_id, request_key, source_client, create_by, create_time from inv_customer_service_record where
and (service_date < #{beforeServiceDate} or (service_date = #{beforeServiceDate} and record_id < #{beforeRecordId}))
order by service_date desc, record_id desc limit #{pageSize}

mapper.update:
update inv_customer_service_profile
set last_visit_date = case when last_visit_date is null or last_visit_date < #{serviceDate}
                           then #{serviceDate} else last_visit_date end,
    version = version + 1, update_by = #{updateBy}, update_time = sysdate()
where customer_id = #{customerId}
  and exists (
      select 1 from inv_customer c
      where c.customer_id = #{customerId} and c.status = '0'
  )
